import { expectTypeOf, test } from 'vitest'
import type { Config, Lead, Page, Product } from './payload-types'

// Generated by `payload generate:types`; these checks fail to compile if the schema and types drift.
test('generated types match the collections the app relies on', () => {
  expectTypeOf<Product['name']>().toEqualTypeOf<string>()
  expectTypeOf<Product['price']>().toEqualTypeOf<number | null | undefined>()
  expectTypeOf<Page['slug']>().toEqualTypeOf<string | null | undefined>()
  expectTypeOf<Lead['kind']>().toEqualTypeOf<'contact' | 'partner'>()
  expectTypeOf<keyof Config['collections']>().toExtend<string>()
})
